import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.yo2CxoV2.js";const k=JSON.parse('{"title":"品牌、主题与导航","description":"","frontmatter":{},"headers":[],"relativePath":"guides/appearance.md","filePath":"guides/appearance.md","lastUpdated":1794337640000}'),d={name:"guides/appearance.md"};function l(n,t,r,o,p,h){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="品牌、主题与导航" tabindex="-1">品牌、主题与导航 <a class="header-anchor" href="#品牌、主题与导航" aria-label="Permalink to &quot;品牌、主题与导航&quot;">​</a></h1><h2 id="项目自己的品牌" tabindex="-1">项目自己的品牌 <a class="header-anchor" href="#项目自己的品牌" aria-label="Permalink to &quot;项目自己的品牌&quot;">​</a></h2><p>在 Django 设置中定义工作空间名称、Logo 和首页标题：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_SITE_TITLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;研究协作平台&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_SITE_SUBTITLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;课题 · 文档 · 研究进展&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_LOGO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/static/brand/logo.svg&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_HOME_TITLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;研究工作台&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_DEFAULT_THEME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;teal&quot;</span></span></code></pre></div><p>这些兼容配置键继续有效。未设置站点标题时使用 <code>admin.site.site_header</code>；项目名称与插件产品品牌分别管理。</p><p><code>ORDLOOM_LOGO</code> 可以是文字或图片路径。图片请放在项目的静态资源中，并跟随部署收集。</p><h2 id="个人外观" tabindex="-1">个人外观 <a class="header-anchor" href="#个人外观" aria-label="Permalink to &quot;个人外观&quot;">​</a></h2><p>从顶栏「外观与体验」调整：</p><table tabindex="0"><thead><tr><th>项目</th><th>可选内容</th></tr></thead><tbody><tr><td>主题</td><td>远山蓝、深海蓝、鸢尾紫、青瓷、松石绿、砂金、胭脂、月白</td></tr><tr><td>显示模式</td><td>浅色、深色、跟随系统</td></tr><tr><td>导航</td><td>浅色或深色侧栏</td></tr><tr><td>信息密度</td><td>舒适或紧凑</td></tr><tr><td>字号</td><td>12、14、16</td></tr><tr><td>圆角</td><td>4、10、16</td></tr><tr><td>内容宽度</td><td>流动或居中限制宽度</td></tr><tr><td>动效</td><td>开启或关闭，并尊重系统减少动态效果设置</td></tr></tbody></table><p>个人偏好保存在当前浏览器，优先于项目默认主题。点击恢复默认可以重新采用项目初始外观。</p><h2 id="页面导航" tabindex="-1">页面导航 <a class="header-anchor" href="#页面导航" aria-label="Permalink to &quot;页面导航&quot;">​</a></h2><ul><li>左侧菜单根据当前账号允许访问的模型生成。</li><li><code>Ctrl/Cmd+K</code> 打开搜索，可输入中文名称、应用分组或 <code>app.model</code>。</li><li>多页面标签保留各页状态；方向键、Home、End 可移动标签焦点，Delete 关闭当前业务标签。</li><li>页面管理菜单支持关闭其他页面或右侧页面。</li><li>模块直达地址使用 <code>/admin/#page=m:projects.project</code>；模型标识含特殊字符时应对参数编码。</li><li>窄屏自动切换抽屉导航，列表在自身容器中横向滚动。</li></ul><h2 id="主题色的使用" tabindex="-1">主题色的使用 <a class="header-anchor" href="#主题色的使用" aria-label="Permalink to &quot;主题色的使用&quot;">​</a></h2><p>前端扩展可使用 <code>--su-bg</code>、<code>--su-surface</code>、<code>--su-text</code>、<code>--su-muted</code>、<code>--su-primary</code> 等变量。主题文字使用 <code>--su-primary</code>；带白字的实色底使用 <code>--su-primary-fill</code>。错误文案使用 <code>--su-error-text</code>。</p><p>主题与新品牌视觉探索不是同一件事。<a href="./../appendix/design.html">附录中的概念图</a>用于讨论未来布局，当前版本能力以实际组件为准。</p>`,15)])])}const u=a(d,[["render",l]]);export{k as __pageData,u as default};
